WITH base AS (SELECT *, CONCAT(location, ' - ', dept_name) AS location_dept_name, ROUND(budget, 1) AS budget_rounded FROM departments WHERE location IS NOT NULL) SELECT id, budget, budget_rounded, ROW_NUMBER() OVER (PARTITION BY location, dept_name ORDER BY budget_rounded, id) AS row_seq, AVG(budget_rounded) OVER (PARTITION BY location ORDER BY budget_rounded, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS budget_rounded_avg_2, NTILE(5) OVER w_running AS budget_bucket, LAST_VALUE(budget_rounded, TRUE) OVER w_recent AS last_known_budget_rounded, AVG(budget) OVER (PARTITION BY location) AS location_avg_budget FROM base WHERE budget > 2145000 WINDOW w_running AS (PARTITION BY dept_name ORDER BY budget, id), w_recent AS (ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
